package dev.kuan.kuanperion.automation;
import java.util.*;
public final class AutomationSafetyTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static ItemSnapshot item(String id,int n,boolean protectedItem){return new ItemSnapshot(id,"minecraft:paper","uuid-"+id,id,"metadata-"+id,n,List.of("lore"),protectedItem);}
 public static void main(String[] args){
  var wheat=item("WHEAT",64,false);var rules=new InventoryProtection(Set.of("WHEAT"),Set.of());
  check(rules.permits(wheat),"explicit exact ID allowed");
  check(!rules.permits(item("WHEAT_HOE",1,false)),"substring not authority");
  check(!new InventoryProtection(Set.of(),Set.of()).permits(wheat),"empty list denies everything");
  check(!rules.permits(item("WHEAT",1,true)),"held/tool/armor/locked protection wins");
  check(!new InventoryProtection(Set.of("WHEAT"),Set.of(wheat.uuid())).permits(wheat),"protected UUID wins");
  check(!new InventoryProtection(Set.of("WHEAT"),Set.of("UUIDWHEAT")).permits(wheat),"UUID formatting/case cannot bypass protection");
  check(!rules.permits(new ItemSnapshot("WHEAT","minecraft:paper","","","",1,List.of(),false)),"missing fingerprint denied");
  var budget=new SpendingBudget(1000);var a=budget.reserve(500,900);check(a!=null&&budget.available()==500,"reservation deducted");
  check(budget.reserve(501,900)==null,"over budget denied");
  check(!budget.commit(a,501)&&budget.available()==500,"cost inflation denied without losing reservation");
  check(budget.commit(a,480)&&budget.spent()==480&&budget.available()==520,"actual receipt cost committed");
  check(!budget.commit(a,1)&&!budget.release(a),"no replay or stale release");
  var b=budget.reserve(500,100);check(b==null,"insufficient purse denied");
  b=budget.reserve(500,900);check(budget.release(b)&&budget.available()==520,"cancel releases hold");
  check(new SpendingBudget(0).reserve(1,1000)==null,"default zero budget fails closed");
  var max=new SpendingBudget(Long.MAX_VALUE);check(max.reserve(Long.MAX_VALUE,Long.MAX_VALUE)!=null&&max.reserve(1,Long.MAX_VALUE)==null,"no overflow");
  var menu=new MenuSnapshot(1,7,3,"Trades",54,List.of(new MenuSnapshot.Slot(49,item("SELL",1,false))));
  var contract=new MenuContract(Set.of("Trades"),54);check(contract.matches(menu),"exact menu contract");
  check(!contract.matches(new MenuSnapshot(1,7,3,"Trades fake",54,menu.slots())),"substring title rejected");
  var ticket=contract.plan(menu,49,MenuContract.Click.PICKUP);check(ticket!=null&&contract.revalidate(ticket,menu),"validated action ticket");
  check(!contract.revalidate(ticket,new MenuSnapshot(1,7,4,"Trades",54,menu.slots())),"server state revision mismatch");
  check(!contract.revalidate(ticket,new MenuSnapshot(2,7,3,"Trades",54,menu.slots())),"world change mismatch");
  check(!contract.revalidate(ticket,new MenuSnapshot(1,8,3,"Trades",54,menu.slots())),"new container mismatch");
  check(!contract.revalidate(ticket,new MenuSnapshot(1,7,3,"Trades",54,List.of(new MenuSnapshot.Slot(49,item("DIFFERENT",1,false))))),"slot identity mismatch");
  check(contract.plan(menu,50,MenuContract.Click.PICKUP)==null,"missing slot fails closed");
  check(MenuContract.exactCoins("Cost: 1,234 Coins")==1234&&MenuContract.exactCoins("Cost: 1.5k Coins")==-1&&MenuContract.exactCoins("Cost: -1 Coins")==-1,"strict unambiguous money parser");
  var coordinator=new AutomationCoordinator();
  var safe=new AutomationContext(1,true,true,Set.of());
  var lease=coordinator.tryAcquire(AutomationFeature.AUTO_SELL,safe,0,1000000000L);
  int[] clicks={0};
  var menuContext=new AutomationContext(1,true,true,Set.of(AutomationContext.Blocker.MENU,AutomationContext.Blocker.INVENTORY_FULL));
  check(GuardedMenuAction.execute(coordinator,lease,contract,ticket,GuardedMenuAction.Space.EXISTING_ITEMS_ONLY,()->menuContext,()->menu,request->{clicks[0]++;return true;},1),"verified owned menu can operate with full inventory for selling");
  check(!GuardedMenuAction.execute(coordinator,lease,contract,ticket,GuardedMenuAction.Space.REQUIRE_FREE_SLOT,()->menuContext,()->menu,request->{throw new AssertionError("full inventory purchase");},2),"purchase requires free space");
  var background=new AutomationContext(1,true,true,Set.of(AutomationContext.Blocker.MENU,AutomationContext.Blocker.FOCUS));
  check(!GuardedMenuAction.execute(coordinator,lease,contract,ticket,GuardedMenuAction.Space.EXISTING_ITEMS_ONLY,()->background,()->menu,request->{throw new AssertionError("background click");},3),"focus protection kept");
  check(!GuardedMenuAction.execute(coordinator,lease,contract,ticket,GuardedMenuAction.Space.EXISTING_ITEMS_ONLY,()->menuContext,()->new MenuSnapshot(1,7,4,"Trades",54,menu.slots()),request->{throw new AssertionError("stale menu click");},4),"live menu rechecked before side effect");
  coordinator.clear();var noScreen=coordinator.tryAcquire(AutomationFeature.STASH,safe,5,1000000000L);
  check(!GuardedMenuAction.execute(coordinator,noScreen,contract,ticket,GuardedMenuAction.Space.EXISTING_ITEMS_ONLY,()->menuContext,()->menu,request->{throw new AssertionError("no SCREEN capability");},6),"Stash cannot click menu");
  check(clicks[0]==1,"only authorized effect emitted");
  var gate=new FarmingHandoff();var token=gate.acquire(1,4,true);check(token!=null&&gate.held(),"acquire armed session hold");
  check(gate.acquire(1,4,true)==null,"no overlapping hold");
  check(!gate.finish(token,2,4,true)&&!gate.held(),"world switch cannot resume");
  token=gate.acquire(2,5,true);gate.invalidate();check(!gate.finish(token,2,5,true),"manual stop invalidates resume");
  token=gate.acquire(2,6,true);check(!gate.finish(token,2,7,true),"new Farming session invalidates resume");
  token=gate.acquire(2,7,true);check(gate.finish(token,2,7,true)&&!gate.held(),"same armed session may continue");
  check(gate.acquire(2,7,false)==null,"no auto enabling disabled farm");
  var receipts=new InventoryReceipts();var stamp=receipts.stamp(1);
  check(!receipts.confirmsDecrease(stamp,0,12,wheat,64),"client prediction alone cannot confirm transaction");
  receipts.observe(1,0,13,new ItemSnapshot("","minecraft:air","","","",0,List.of(),true));
  check(!receipts.confirmsDecrease(stamp,0,12,wheat,64),"unrelated slot packet not receipt");
  receipts.observe(1,0,12,new ItemSnapshot("","minecraft:air","","","",0,List.of(),true));
  check(receipts.confirmsDecrease(stamp,0,12,wheat,64),"fresh server packet confirms exact authorized slot decrease");
  var newer=receipts.stamp(1);check(!receipts.confirmsDecrease(newer,0,12,wheat,64),"old packet not replayed");
  receipts.observe(2,0,12,new ItemSnapshot("","minecraft:air","","","",0,List.of(),true));
  check(!receipts.confirmsDecrease(stamp,0,12,wheat,64),"different world receipt rejected");
  AutomationContext[] live={safe};int[] hooks={0,0};var owner=new AutomationCoordinator();
  var session=new AutomationSession(owner,()->live[0],()->hooks[0]++,()->hooks[1]++);
  var task=session.begin(AutomationFeature.PEST,0,1000000000L);
  check(task!=null&&session.holdsFarming()&&hooks[0]==1,"task holds original farm without changing arm flag");
  check(session.begin(AutomationFeature.COMPOSTER,1,1000000000L)==null,"exclusive task");
  check(session.finish(task,true,2)&&hooks[1]==0&&!session.holdsFarming(),"same-session success releases hold without re-enabling farm");
  task=session.begin(AutomationFeature.PEST,3,1000000000L);session.invalidate();
  check(!session.finish(task,true,4)&&hooks[1]==0,"manual stop invalidates token, cannot re-enable or stop a new session");
  task=session.begin(AutomationFeature.PEST,5,1000000000L);session.finish(task,false,6);
  check(hooks[1]==1&&!session.holdsFarming(),"failure invokes safe stop instead of blindly resuming at wrong position");
  task=session.begin(AutomationFeature.PEST,7,1000000000L);live[0]=new AutomationContext(2,true,true,Set.of());session.poll(8);
  check(!session.active()&&hooks[1]==2,"world transition invalidates and safe-stops old task");
  live[0]=new AutomationContext(2,false,true,Set.of());task=session.begin(AutomationFeature.COMPOSTER,9,1000000000L);
  check(task!=null&&!session.holdsFarming(),"manual maintenance does not arm disabled Farming");session.finish(task,true,10);check(hooks[1]==2,"manual completion does not toggle Farming");
  live[0]=safe;task=session.begin(AutomationFeature.AUTO_SELL,11,1000000000L);live[0]=new AutomationContext(1,true,true,Set.of(AutomationContext.Blocker.MENU));session.poll(12);
  check(!session.active()&&hooks[1]==3,"unexpected GUI invalidates hold instead of resuming underneath user menu");
  live[0]=safe;task=session.begin(AutomationFeature.AUTO_SELL,13,1000000000L);MenuSnapshot[] observedMenu={menu};session.expectMenu(task,contract,()->observedMenu[0]);
  live[0]=new AutomationContext(1,true,true,Set.of(AutomationContext.Blocker.MENU));session.poll(14);check(session.active(),"explicit expected menu accepted");
  observedMenu[0]=new MenuSnapshot(1,8,3,"Trades",54,menu.slots());session.poll(15);check(!session.active()&&hooks[1]==4,"different container with same title is not silently adopted");
  System.out.println("AutomationSafetyTest: PASS (exact inventory authorization, protection, reservation/receipt budget, menu identity/revision tickets, Farming session handoff)");
 }
}
